423: export function learnMoves(mon) {
424:   const sp = species(mon.id)
425:   if (!sp) return []
426:   const known = new Set(mon.moves.map(m => m.id))
427:   const candidates = (sp.learnset || [])
428:     .filter(x => x.level <= mon.level && POKEDEX.moves[x.move] && !known.has(x.move))
429:     .sort((a, b) => a.level - b.level)
430:   const learned = []
431:   for (const entry of candidates) {
432:     if (mon.moves.length < 4) {
433:       mon.moves.push({ id: entry.move, pp: POKEDEX.moves[entry.move].pp, maxPp: POKEDEX.moves[entry.move].pp })
434:       learned.push(entry.move)
435:     } else {
436:       const replaceIndex = mon.moves.findIndex(m => (POKEDEX.moves[m.id]?.power || 0) === 0)
437:       const idx = replaceIndex >= 0 ? replaceIndex : 0
438:       mon.moves[idx] = { id: entry.move, pp: POKEDEX.moves[entry.move].pp, maxPp: POKEDEX.moves[entry.move].pp }
439:       learned.push(entry.move)
440:     }
441:     known.add(entry.move)
442:     if (learned.length >= 2) break
443:   }
444:   return learned
445: }
