251: async function playerMove(index) {
252:   if (!battle || battle.busy || battle.over) return
253:   const pm = allyMon()
254:   if (!pm) return
255:   let slot
256:   if (index === 'struggle') {
257:     slot = { id: 'struggle', pp: 1, maxPp: 1 }
258:   } else {
259:     slot = pm.moves[index]
260:     if (!slot) return
261:     if (slot.pp <= 0) {
262:       audio.sfx('error')
263:       await say(t('battleNoPP', { move: displayMove(slot.id) }), 650)
264:       renderActions('fight')
265:       return
266:     }
267:   }
268:   battle.busy = true
269:   renderActions()
270:   const eMove = chooseEnemyMove()
271:   const first = playerFirst(slot.id, eMove)
272:   if (first) {
273:     await performMove(pm, enemyMon(), slot, true)
274:     if (!battle.over && enemyMon()?.hp > 0) await performMove(enemyMon(), allyMon(), eMove, false)
275:   } else {
276:     await performMove(enemyMon(), allyMon(), eMove, false)
277:     if (!battle.over && allyMon()?.hp > 0) await performMove(allyMon(), enemyMon(), slot, true)
278:   }
279:   if (!battle.over) await endOfTurn()
280:   if (battle && !battle.over) {
281:     battle.busy = false
282:     renderActions('main')
283:   }
284: }
