414: async function endOfTurn() {
415:   if (!battle || battle.over) return
416:   for (const mon of [enemyMon(), allyMon()]) {
417:     if (!mon || mon.hp <= 0) continue
418:     if (mon.status === 'burn' || mon.status === 'poison') {
419:       const dmg = Math.max(1, Math.floor(mon.maxHp / (mon.status === 'burn' ? 16 : 8)))
420:       mon.hp = Math.max(0, mon.hp - dmg)
421:       audio.sfx('hit')
422:       await say(t('battleStatusHurt', { name: monName(mon), status: statusLabel(mon.status) }), 600)
423:       renderBattleUI()
424:       if (mon.hp <= 0) { await faint(mon); return }
425:     }
426:     mon.protected = false
427:     mon.flinched = false
428:   }
429: }
