573: async function tryRun() {
574:   if (!battle || battle.busy || battle.over) return
575:   if (!battle.isWild) {
576:     audio.sfx('error')
577:     await say(t('battleCantRun'), 700)
578:     renderActions('main')
579:     return
580:   }
581:   battle.busy = true
582:   renderActions()
583:   const pm = allyMon()
584:   const em = enemyMon()
585:   const chance = clamp(0.55 + (speedOf(pm) - speedOf(em)) / 220, 0.25, 0.95)
586:   if (Math.random() < chance) {
587:     await say(t('battleRan'), 700)
588:     closeBattle('run')
