97: function smooth(t) { return t * t * (3 - 2 * t) }
98: function noise2(x, y, seed) {
99:   const xi = Math.floor(x), yi = Math.floor(y)
100:   const xf = smooth(x - xi), yf = smooth(y - yi)
101:   const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed)
102:   const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed)
103:   return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf
104: }
