106: function distToSegment(px, py, x1, y1, x2, y2) {
107:   const dx = x2 - x1, dy = y2 - y1
108:   const len = dx * dx + dy * dy
109:   let t = len ? ((px - x1) * dx + (py - y1) * dy) / len : 0
110:   t = Math.max(0, Math.min(1, t))
111:   const x = x1 + t * dx, y = y1 + t * dy
112:   return Math.hypot(px - x, py - y)
113: }
