261:     // Hedge border.
262:     for (let y = 0; y < MAP_H; y++) for (let x = 0; x < MAP_W; x++) {
263:       if (x < 2 || y < 2 || x >= MAP_W - 2 || y >= MAP_H - 2) this.set(x, y, T.HEDGE)
264:     }
265:     // A few hedge clusters.
266:     for (let i = 0; i < 22; i++) {
267:       const cx = 8 + Math.floor(rand() * (MAP_W - 16)), cy = 8 + Math.floor(rand() * (MAP_H - 16))
268:       if (this.nearPath(cx, cy, 5) || this.nearPlaza(cx, cy, 11)) continue
269:       const len = 2 + Math.floor(rand() * 4)
270:       const horiz = rand() > .5
271:       for (let j = 0; j < len; j++) {
272:         const x = cx + (horiz ? j : 0), y = cy + (horiz ? 0 : j)
273:         if (this.get(x, y) === T.GRASS || this.get(x, y) === T.FLOWER || this.get(x, y) === T.TALL) this.set(x, y, T.HEDGE)
274:       }
275:     }
276: 
277:     this.buildProps(rand)
278:     this.buildArenas()
279:     this.buildNPCs()
280:     this.buildBaseCanvas()
281:     this.buildMiniCanvas()
282:   }
283: 
284:   carveCircle(cx, cy, r, tile) {
285:     for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++) {
286:       for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
287:         if (Math.hypot(x + .5 - cx, y + .5 - cy) <= r) this.set(x, y, tile)
288:       }
289:     }
290:   }
291: 
292:   nearPath(x, y, d) {
293:     for (const p of PATHS) {
294:       for (let i = 0; i < p.points.length - 1; i++) {
295:         const a = p.points[i], b = p.points[i + 1]
296:         if (distToSegment(x + .5, y + .5, a[0], a[1], b[0], b[1]) < d) return true
297:       }
298:     }
299:     return false
300:   }
301: 
302:   nearPlaza(x, y, d) {
303:     if (Math.hypot(x - 70, y - 96) < d) return true
304:     if (Math.hypot(x - 70, y - 57) < d) return true
305:     return ARENA_DEFS.some(a => Math.hypot(x - a.x, y - a.y) < d)
306:   }
307: 
308:   zoneAtTile(x, y) {
309:     let best = this.zones[0], bd = 1e9
310:     for (const z of this.zones) {
311:       const d = Math.hypot(x - z.x, y - z.y) / z.r
312:       if (d < bd) { bd = d; best = z }
313:     }
314:     return best
315:   }
316: 
317:   zoneAt(px, py) {
318:     return this.zoneAtTile(px / TILE, py / TILE)
319:   }
