321:   buildProps(rand) {
322:     const props = []
323:     // Trees.
324:     for (let y = 4; y < MAP_H - 4; y++) {
325:       for (let x = 4; x < MAP_W - 4; x++) {
326:         const tile = this.get(x, y)
327:         if (tile !== T.GRASS && tile !== T.FLOWER && tile !== T.TALL) continue
328:         if (this.nearPath(x, y, 2.6) || this.nearPlaza(x, y, 9)) continue
329:         const zone = this.zoneAtTile(x, y)
330:         let chance = .035
331:         if (zone.id === 'rose') chance = .065
332:         if (zone.id === 'lake') chance = .05
333:         if (zone.id === 'greenhouse') chance = .04
334:         if (zone.id === 'fireflies') chance = .06
335:         if (Math.hypot(x - 70, y - 57) > 18 && Math.hypot(x - 70, y - 57) < 26) chance = .085
336:         if (rand() < chance) {
337:           const type = zone.id === 'rose' ? (rand() < .45 ? 'blossom' : 'broad') : zone.id === 'greenhouse' ? (rand() < .35 ? 'pine' : 'broad') : zone.id === 'fireflies' ? (rand() < .3 ? 'pine' : 'broad') : 'broad'
338:           const scale = .78 + rand() * .5
339:           props.push({ kind: 'tree', x: (x + .5) * TILE + (rand() - .5) * 12, y: (y + .65) * TILE, scale, type, seed: rand() * 10, baseY: (y + .65) * TILE })
340:         }
341:       }
342:     }
343:     // Border tree line.
344:     for (let i = 0; i < 180; i++) {
345:       const side = Math.floor(rand() * 4)
346:       let x, y
347:       if (side === 0) { x = 3 + rand() * (MAP_W - 6); y = 3 + rand() * 4 }
348:       else if (side === 1) { x = 3 + rand() * (MAP_W - 6); y = MAP_H - 4 - rand() * 4 }
349:       else if (side === 2) { x = 3 + rand() * 4; y = 3 + rand() * (MAP_H - 6) }
350:       else { x = MAP_W - 4 - rand() * 4; y = 3 + rand() * (MAP_H - 6) }
351:       if (this.nearPath(x, y, 2.5)) continue
352:       const scale = .9 + rand() * .65
353:       props.push({ kind: 'tree', x: x * TILE, y: y * TILE, scale, type: rand() < .3 ? 'pine' : 'broad', seed: rand() * 10, baseY: y * TILE })
354:     }
355:     // Rocks, mushrooms, bushes.
356:     for (let i = 0; i < 120; i++) {
357:       const x = 5 + Math.floor(rand() * (MAP_W - 10)), y = 5 + Math.floor(rand() * (MAP_H - 10))
358:       const tile = this.get(x, y)
359:       if (![T.GRASS, T.FLOWER, T.TALL, T.SAND].includes(tile) || this.nearPath(x, y, 1.7) || this.nearPlaza(x, y, 8)) continue
360:       const r = rand()
361:       props.push({ kind: r < .45 ? 'rock' : r < .75 ? 'mushroom' : 'bush', x: (x + .5) * TILE, y: (y + .6) * TILE, scale: .6 + rand() * .7, seed: rand() * 10, baseY: (y + .6) * TILE })
362:     }
363:     // Lamps along the main paths.
364:     for (let i = 0; i < 26; i++) {
365:       const p = PATHS[Math.floor(rand() * 5)]
366:       const seg = Math.floor(rand() * (p.points.length - 1))
367:       const a = p.points[seg], b = p.points[seg + 1]
368:       const t = rand()
369:       const x = (a[0] + (b[0] - a[0]) * t + (rand() - .5) * 5) * TILE
370:       const y = (a[1] + (b[1] - a[1]) * t + (rand() - .5) * 5) * TILE
371:       const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE)
372:       if (this.isWalkableTile(tx, ty) && !this.nearPlaza(tx, ty, 7)) props.push({ kind: 'lamp', x, y, scale: .8 + rand() * .35, seed: rand() * 10, baseY: y })
373:     }
374:     // Benches, flower pots and market stall.
375:     props.push({ kind: 'stall', x: 79 * TILE, y: 98 * TILE, scale: 1, seed: 1, baseY: 98 * TILE })
376:     props.push({ kind: 'bench', x: 64 * TILE, y: 93 * TILE, scale: 1, seed: 2, baseY: 93 * TILE })
377:     props.push({ kind: 'bench', x: 72 * TILE, y: 64 * TILE, scale: 1, seed: 3, baseY: 64 * TILE })
378:     props.push({ kind: 'bench', x: 58 * TILE, y: 70 * TILE, scale: 1, seed: 4, baseY: 70 * TILE })
379:     for (const s of SIGN_DEFS) {
380:       props.push({ kind: 'sign', x: s.x * TILE + TILE / 2, y: s.y * TILE + TILE / 2, scale: 1, seed: 1, baseY: s.y * TILE + TILE / 2 })
381:     }
382:     for (const a of ARENA_DEFS) {
383:       for (let i = 0; i < 4; i++) {
384:         const ang = i * Math.PI / 2 + .4
385:         props.push({ kind: 'pot', x: (a.x + Math.cos(ang) * 6.5) * TILE, y: (a.y + Math.sin(ang) * 6.5) * TILE, scale: 1, seed: i, baseY: (a.y + Math.sin(ang) * 6.5) * TILE })
386:       }
387:     }
388:     // Fountain and heart.
389:     props.push({ kind: 'fountain', x: this.fountain.x * TILE, y: this.fountain.y * TILE, scale: 1, baseY: this.fountain.y * TILE })
390:     props.push({ kind: 'heart', x: this.heart.x * TILE, y: this.heart.y * TILE, scale: 1, baseY: this.heart.y * TILE })
391:     this.props = props
392:     this.trees = props.filter(p => p.kind === 'tree')
393:   }
