423:     npcs.push({ id: 'villager3', kind: 'villager', name: 'Margot', x: 64 * TILE, y: 90 * TILE, palette: '#c77d9b', baseY: 90 * TILE, dialogue: 'npcVillager3', nameKey: 'villager3' })
