444:   buildBaseCanvas() {
445:     const S = 16
446:     const canvas = document.createElement('canvas')
447:     canvas.width = MAP_W * S
448:     canvas.height = MAP_H * S
449:     const ctx = canvas.getContext('2d')
450:     for (let y = 0; y < MAP_H; y++) {
451:       for (let x = 0; x < MAP_W; x++) {
452:         const t = this.get(x, y)
453:         const n = hash2(x, y, this.seedNum)
454:         let color = '#77b45b'
455:         if (t === T.GRASS) color = n > .5 ? '#78b75a' : '#72b056'
456:         else if (t === T.PATH) color = n > .5 ? '#e6cf9e' : '#dfc68f'
457:         else if (t === T.WATER) color = n > .5 ? '#66bed2' : '#60b6cc'
458:         else if (t === T.TALL) color = n > .5 ? '#5b9b49' : '#569447'
459:         else if (t === T.FLOWER) color = n > .5 ? '#7fbb5c' : '#78b459'
460:         else if (t === T.STONE) color = n > .5 ? '#d9d2b6' : '#d2caae'
461:         else if (t === T.HEDGE) color = n > .5 ? '#3f7a46' : '#3a7141'
462:         else if (t === T.SAND) color = n > .5 ? '#e6d39d' : '#dfcb94'
463:         else if (t === T.BRIDGE) color = n > .5 ? '#b9895f' : '#af8058'
464:         else if (t === T.SOIL) color = n > .5 ? '#a97450' : '#9e6a49'
465:         else if (t === T.ROCK) color = '#9a9a86'
466:         ctx.fillStyle = color
467:         ctx.fillRect(x * S, y * S, S, S)
468:         // Painterly speckles.
469:         if (t === T.GRASS || t === T.TALL || t === T.FLOWER) {
470:           ctx.fillStyle = n > .5 ? 'rgba(255,255,255,.055)' : 'rgba(20,60,30,.05)'
471:           ctx.fillRect(x * S + (n * 10 | 0), y * S + ((n * 31) % 10 | 0), 3, 2)
472:         }
473:         if (t === T.PATH) {
474:           ctx.fillStyle = 'rgba(120,85,45,.09)'
475:           ctx.fillRect(x * S + 3 + (n * 6 | 0), y * S + 4 + (n * 5 | 0), 2, 2)
476:         }
477:         if (t === T.WATER) {
478:           ctx.fillStyle = 'rgba(255,255,255,.12)'
479:           ctx.fillRect(x * S + 2, y * S + 3 + (n * 8 | 0), 6, 1)
480:         }
481:         if (t === T.STONE) {
482:           ctx.fillStyle = 'rgba(90,80,55,.09)'
483:           ctx.fillRect(x * S + 2, y * S + 2, 5, 1)
484:           ctx.fillRect(x * S + 7, y * S + 9, 5, 1)
485:         }
486:         if (t === T.HEDGE) {
487:           ctx.fillStyle = 'rgba(20,60,25,.16)'
488:           ctx.beginPath(); ctx.arc(x * S + 4, y * S + 6, 2.2, 0, 7); ctx.fill()
489:           ctx.beginPath(); ctx.arc(x * S + 10, y * S + 11, 2.8, 0, 7); ctx.fill()
490:         }
491:         if (t === T.SOIL) {
492:           ctx.fillStyle = 'rgba(70,40,20,.15)'
493:           ctx.fillRect(x * S + 2, y * S + 2, 11, 1)
494:           ctx.fillRect(x * S + 2, y * S + 8, 11, 1)
495:         }
496:         if (t === T.BRIDGE) {
497:           ctx.fillStyle = 'rgba(70,40,20,.18)'
498:           ctx.fillRect(x * S, y * S + 3, S, 1)
499:           ctx.fillRect(x * S, y * S + 9, S, 1)
500:         }
501:       }
502:     }
503:     // Soft path edges: overlay small grass tufts along path borders.
504:     for (let y = 2; y < MAP_H - 2; y++) for (let x = 2; x < MAP_W - 2; x++) {
505:       if (this.get(x, y) !== T.PATH) continue
506:       const edges = [[1, 0], [-1, 0], [0, 1], [0, -1]]
507:       for (const [dx, dy] of edges) {
508:         if (this.get(x + dx, y + dy) === T.GRASS || this.get(x + dx, y + dy) === T.TALL) {
509:           ctx.fillStyle = 'rgba(67,135,55,.5)'
510:           const ex = (x + (dx > 0 ? 1 : 0)) * S, ey = (y + (dy > 0 ? 1 : 0)) * S
511:           for (let i = 0; i < 4; i++) {
512:             const px = ex + (dx ? 0 : (i * 4 + 1)), py = ey + (dy ? 0 : (i * 4 + 1))
513:             ctx.beginPath(); ctx.arc(px, py, 2.1, 0, 7); ctx.fill()
514:           }
515:         }
516:       }
517:     }
518:     this.baseCanvas = canvas
519:   }
