534:   isSolid(px, py, radius = 9) {
535:     const points = [[px - radius, py - radius], [px + radius, py - radius], [px - radius, py + radius], [px + radius, py + radius]]
536:     for (const [x, y] of points) {
537:       const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE)
538:       const t = this.get(tx, ty)
539:       if (t === T.WATER || t === T.HEDGE) return true
540:     }
541:     for (const tree of this.trees) {
542:       if (Math.abs(tree.x - px) > 40 || Math.abs(tree.y - py) > 40) continue
543:       if (Math.hypot(tree.x - px, tree.y - (py + 4)) < 9 * tree.scale + radius * .55) return true
544:     }
545:     for (const prop of this.props) {
546:       if (prop.kind === 'rock' && Math.hypot(prop.x - px, prop.y - py) < 10 * prop.scale + radius * .4) return true
547:     }
548:     return false
549:   }
550: 
551:   isTall(px, py) {
552:     return this.get(Math.floor(px / TILE), Math.floor(py / TILE)) === T.TALL
553:   }
554: 
555:   getDrawables(cam) {
556:     const pad = 80
557:     const left = cam.x - cam.vw / 2 / cam.zoom - pad
558:     const right = cam.x + cam.vw / 2 / cam.zoom + pad
559:     const top = cam.y - cam.vh / 2 / cam.zoom - pad
560:     const bottom = cam.y + cam.vh / 2 / cam.zoom + pad
561:     const out = []
562:     for (const p of this.props) {
563:       if (p.x > left && p.x < right && p.y > top && p.y < bottom) out.push(p)
564:     }
565:     return out
566:   }
567: 
568:   drawGround(ctx, cam, time) {
569:     ctx.imageSmoothingEnabled = true
570:     ctx.drawImage(this.baseCanvas, 0, 0, WORLD_W, WORLD_H)
571:     const left = Math.max(0, Math.floor((cam.x - cam.vw / 2 / cam.zoom) / TILE) - 1)
572:     const right = Math.min(MAP_W - 1, Math.ceil((cam.x + cam.vw / 2 / cam.zoom) / TILE) + 1)
573:     const top = Math.max(0, Math.floor((cam.y - cam.vh / 2 / cam.zoom) / TILE) - 1)
574:     const bottom = Math.min(MAP_H - 1, Math.ceil((cam.y + cam.vh / 2 / cam.zoom) / TILE) + 1)
575:     for (let y = top; y <= bottom; y++) {
576:       for (let x = left; x <= right; x++) {
577:         const t = this.get(x, y)
578:         if (t === T.WATER || t === T.LILY) this.drawWater(ctx, x, y, time)
579:         else if (t === T.TALL) this.drawTallGrass(ctx, x, y, time)
580:         else if (t === T.FLOWER) this.drawFlowers(ctx, x, y, time)
581:         else if (t === T.HEDGE) this.drawHedge(ctx, x, y, time)
582:         else if (t === T.STONE) this.drawStone(ctx, x, y)
583:       }
584:     }
585:   }
586: 
587:   drawWater(ctx, x, y, time) {
588:     const bx = x * TILE, by = y * TILE
589:     const n = hash2(x, y, this.seedNum)
590:     ctx.fillStyle = 'rgba(255,255,255,.18)'
591:     for (let i = 0; i < 2; i++) {
592:       const ox = (Math.sin(time * .7 + x * 1.7 + i * 2.2 + n * 9) * 7) | 0
593:       ctx.fillRect(bx + 5 + ox, by + 8 + i * 10, 11, 1.3)
594:     }
595:     if (n > .8) {
596:       ctx.fillStyle = '#67a94f'
597:       ctx.beginPath(); ctx.ellipse(bx + 16, by + 16, 6, 3.5, .4, 0, 7); ctx.fill()
598:       ctx.fillStyle = '#ffc2d1'
599:       ctx.beginPath(); ctx.arc(bx + 17, by + 15, 2, 0, 7); ctx.fill()
600:     }
601:   }
602: 
603:   drawTallGrass(ctx, x, y, time) {
604:     const bx = x * TILE, by = y * TILE
605:     const n = hash2(x, y, this.seedNum)
606:     const sway = Math.sin(time * 2.1 + x * .7 + y * .4) * 1.5
607:     for (let i = 0; i < 5; i++) {
608:       const ox = 4 + i * 6 + (n * 4 | 0)
609:       const h = 10 + (hash2(x * 5 + i, y, this.seedNum) * 9)
610:       ctx.strokeStyle = i % 2 ? 'rgba(37,104,43,.75)' : 'rgba(63,132,53,.7)'
611:       ctx.lineWidth = 1.6
612:       ctx.lineCap = 'round'
613:       ctx.beginPath()
614:       ctx.moveTo(bx + ox, by + 30)
615:       ctx.quadraticCurveTo(bx + ox + sway, by + 30 - h * .6, bx + ox + sway * 1.7, by + 30 - h)
616:       ctx.stroke()
617:     }
618:     if (n > .85) {
619:       ctx.fillStyle = '#f4d36a'
620:       ctx.beginPath(); ctx.arc(bx + 22, by + 15, 1.7, 0, 7); ctx.fill()
621:     }
622:   }
623: 
624:   drawFlowers(ctx, x, y, time) {
