74: export function rngFor(seed) {
75:   let a = typeof seed === 'number' ? seed : hashString(seed)
76:   return function () {
77:     a |= 0; a = a + 0x6D2B79F5 | 0
78:     let t = Math.imul(a ^ a >>> 15, 1 | a)
79:     t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
80:     return ((t ^ t >>> 14) >>> 0) / 4294967296
81:   }
82: }
