84: export function hashString(str) {
85:   let h = 2166136261
86:   for (let i = 0; i < String(str).length; i++) {
87:     h ^= String(str).charCodeAt(i)
88:     h = Math.imul(h, 16777619)
89:   }
90:   return h >>> 0
91: }
