231: export function makeMon(id, level, opts = {}) {
232:   const sid = safeSpecies(id)
233:   const sp = species(sid)
234:   const lv = clamp(Math.round(level || 5), 1, 100)
235:   const st = calcStats(sp, lv)
236:   const learn = (sp.learnset || [])
237:     .filter(x => x.level <= lv && POKEDEX.moves[x.move])
238:     .sort((a, b) => a.level - b.level)
239:   const seen = new Set()
240:   let moveIds = []
241:   for (let i = learn.length - 1; i >= 0 && moveIds.length < 4; i--) {
242:     if (!seen.has(learn[i].move)) { seen.add(learn[i].move); moveIds.unshift(learn[i].move) }
243:   }
244:   if (!moveIds.length) moveIds = ['tackle']
245:   const hasDamage = moveIds.some(m => (POKEDEX.moves[m]?.power || 0) > 0)
246:   if (!hasDamage) moveIds[moveIds.length - 1] = 'tackle'
247:   const moves = moveIds.map(m => ({
248:     id: m,
249:     pp: POKEDEX.moves[m]?.pp || 10,
250:     maxPp: POKEDEX.moves[m]?.pp || 10
251:   }))
252:   const mon = {
253:     id: sid,
254:     level: lv,
255:     exp: 0,
256:     hp: st.hp,
257:     maxHp: st.hp,
258:     stats: st,
259:     moves,
260:     status: '',
261:     sleepTurns: 0,
262:     stages: { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 },
263:     lost: false,
264:     protected: false,
265:     flinched: false,
266:     shiny: !!opts.shiny,
267:     origin: opts.origin || ''
268:   }
269:   return mon
270: }
