276:   mon.stats = { ...base.stats, ...(raw.stats || {}) }
277:   mon.moves = (raw.moves || base.moves).filter(m => m && POKEDEX.moves[m.id]).map(m => ({
278:     id: m.id,
279:     pp: typeof m.pp === 'number' ? m.pp : (POKEDEX.moves[m.id]?.pp || 10),
280:     maxPp: m.maxPp || POKEDEX.moves[m.id]?.pp || 10
281:   }))
282:   if (!mon.moves.length) mon.moves = base.moves
283:   mon.stages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, ...(raw.stages || {}) }
284:   mon.maxHp = Math.max(1, raw.maxHp || base.maxHp)
285:   mon.hp = clamp(raw.hp == null ? mon.maxHp : raw.hp, 0, mon.maxHp)
286:   return mon
287: }
