410: export function addExp(mon, amount) {
411:   if (!mon || mon.lost) return { levels: 0, learned: [] }
412:   mon.exp += amount
413:   let levels = 0
414:   while (mon.level < 100 && mon.exp >= expNeeded(mon.level)) {
415:     mon.exp -= expNeeded(mon.level)
416:     mon.level++
417:     levels++
418:     recalcStats(mon)
419:   }
420:   return { levels }
421: }
