451:   if (!POKEDEX.species[sp.evolvesTo]) return null
452:   const oldName = monName(mon)
453:   mon.id = sp.evolvesTo
454:   recalcStats(mon)
455:   healMon(mon)
456:   const newSp = species(mon.id)
457:   return { oldName, newName: speciesName(mon.id), species: newSp }
458: }
