460: export function randomStarterIds(rng, count = 3) {
461:   const pool = POKEDEX.firstStage.filter(id => POKEDEX.species[id])
462:   const shuffled = shuffle(pool, rng)
463:   const chosen = []
464:   const usedTypes = new Set()
465:   for (const id of shuffled) {
466:     const sp = species(id)
467:     if (!sp) continue
468:     const primary = sp.types[0]
469:     if (usedTypes.has(primary) && chosen.length < count) continue
470:     chosen.push(id)
471:     usedTypes.add(primary)
472:     if (chosen.length >= count) break
473:   }
474:   if (chosen.length < count) {
475:     for (const id of shuffled) {
476:       if (!chosen.includes(id)) chosen.push(id)
477:       if (chosen.length >= count) break
478:     }
479:   }
480:   return chosen.slice(0, count)
481: }
