504: class AudioManager {
505:   constructor() {
506:     this.enabled = true
507:     this.ctx = null
508:     this.musicTimer = null
509:     this.scene = 'title'
510:     this.step = 0
511:     this.cryCache = new Map()
512:     try {
513:       const saved = localStorage.getItem(SOUND_KEY)
514:       if (saved === 'off') this.enabled = false
515:     } catch {}
516:   }
517: 
518:   setEnabled(on) {
519:     this.enabled = !!on
520:     try { localStorage.setItem(SOUND_KEY, this.enabled ? 'on' : 'off') } catch {}
521:     if (!this.enabled) this.stopMusic()
522:     else this.startMusic()
523:   }
524: 
525:   ensure() {
526:     if (!this.enabled) return null
527:     try {
528:       if (!this.ctx) {
529:         const Ctx = window.AudioContext || window.webkitAudioContext
530:         if (!Ctx) return null
531:         this.ctx = new Ctx()
532:       }
533:       if (this.ctx.state === 'suspended') this.ctx.resume()
534:       return this.ctx
535:     } catch { return null }
536:   }
537: 
538:   tone(freq, dur = 0.12, type = 'sine', vol = 0.045, delay = 0) {
539:     const ctx = this.ensure()
540:     if (!ctx) return
541:     try {
542:       const osc = ctx.createOscillator()
543:       const gain = ctx.createGain()
544:       const t0 = ctx.currentTime + delay
545:       osc.type = type
546:       osc.frequency.setValueAtTime(freq, t0)
547:       gain.gain.setValueAtTime(0.0001, t0)
548:       gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.012)
549:       gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
