534:   isSolid(px, py, radius = 9) {
535:     const points = [[px - radius, py - radius], [px + radius, py - radius], [px - radius, py + radius], [px + radius, py + radius]]
536:     for (const [x, y] of points) {
537:       const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE)
538:       const t = this.get(tx, ty)
539:       if (t === T.WATER || t === T.HEDGE) return true
540:     }
541:     for (const tree of this.trees) {
542:       if (Math.abs(tree.x - px) > 40 || Math.abs(tree.y - py) > 40) continue
543:       if (Math.hypot(tree.x - px, tree.y - (py + 4)) < 9 * tree.scale + radius * .55) return true
544:     }
545:     for (const prop of this.props) {
546:       if (prop.kind === 'rock' && Math.hypot(prop.x - px, prop.y - py) < 10 * prop.scale + radius * .4) return true
547:     }
548:     return false
549:   }
