555:   getDrawables(cam) {
556:     const pad = 80
557:     const left = cam.x - cam.vw / 2 / cam.zoom - pad
558:     const right = cam.x + cam.vw / 2 / cam.zoom + pad
559:     const top = cam.y - cam.vh / 2 / cam.zoom - pad
560:     const bottom = cam.y + cam.vh / 2 / cam.zoom + pad
561:     const out = []
562:     for (const p of this.props) {
563:       if (p.x > left && p.x < right && p.y > top && p.y < bottom) out.push(p)
564:     }
565:     return out
566:   }
