239: function playerFirst(pMoveId, eMoveId) {
240:   const pd = moveData(pMoveId)
241:   const ed = moveData(eMoveId)
242:   const pp = pd?.priority || 0
243:   const ep = ed?.priority || 0
244:   if (pp !== ep) return pp > ep
245:   const ps = speedOf(allyMon())
246:   const es = speedOf(enemyMon())
247:   if (ps === es) return Math.random() < 0.5
248:   return ps > es
249: }
