286: async function performMove(attacker, defender, slot, isPlayer) {
287:   if (!battle || battle.over || !attacker || !defender) return
288:   if (attacker.hp <= 0 || defender.hp <= 0) return
289:   if (attacker.flinched) {
290:     attacker.flinched = false
291:     await say(t('battleFlinch', { name: monName(attacker) }), 600)
292:     return
293:   }
294:   if (attacker.status === 'sleep') {
295:     if (attacker.sleepTurns > 0) {
296:       attacker.sleepTurns--
297:       await say(t('battleSleep', { name: monName(attacker) }), 650)
298:       if (attacker.sleepTurns <= 0) {
299:         attacker.status = ''
300:         await say(t('battleStatusFree', { name: monName(attacker), status: statusLabel('sleep') }), 650)
301:       }
302:       return
303:     }
304:     attacker.status = ''
305:   }
306:   if (attacker.status === 'paralysis' && Math.random() < 0.25) {
307:     await say(t('battleParalyzed', { name: monName(attacker) }), 650)
308:     return
309:   }
310:   const md = moveData(slot.id)
311:   if (!md) return
312:   if (slot.id !== 'struggle' && typeof slot.pp === 'number') slot.pp = Math.max(0, slot.pp - 1)
313:   const type = moveTypeFor(slot.id)
314:   await say(t('battleUsed', { name: monName(attacker), move: displayMove(slot.id) }), 620)
315:   if (defender.protected) {
316:     defender.protected = false
317:     await say(t('battleProtected', { name: monName(defender) }), 650)
318:     return
319:   }
320:   const acc = md.accuracy == null ? 100 : md.accuracy
321:   if (Math.random() * 100 >= acc) {
322:     await say(t('battleMiss', { name: monName(attacker) }), 620)
323:     return
324:   }
325:   let dealt = 0
326:   if ((md.power || 0) > 0) {
327:     const defTypes = species(defender.id)?.types || []
328:     const eff = effectiveness(type, defTypes)
329:     if (eff === 0) {
330:       await say(t('battleNoEffect', { name: monName(defender) }), 650)
331:       return
332:     }
333:     const physical = md.class !== 'special'
334:     const atkStat = physical ? 'atk' : 'spa'
335:     const defStat = physical ? 'def' : 'spd'
336:     let atk = attacker.stats[atkStat] * stageMultiplier(attacker.stages[atkStat])
337:     let def = defender.stats[defStat] * stageMultiplier(defender.stages[defStat])
338:     if (physical && attacker.status === 'burn') atk *= 0.5
339:     const crit = Math.random() < (md.crit ? 0.12 : 1 / 16)
340:     const stab = species(attacker.id)?.types.includes(type) ? 1.5 : 1
341:     const rand = 0.85 + Math.random() * 0.15
342:     let dmg = (((2 * attacker.level / 5 + 2) * md.power * atk / Math.max(1, def)) / 50 + 2) * stab * eff * rand
343:     if (crit) dmg *= 1.5
344:     dmg = Math.max(1, Math.floor(dmg))
345:     dealt = Math.min(defender.hp, dmg)
346:     defender.hp = Math.max(0, defender.hp - dmg)
347:     if (isPlayer) animate($('enemySprite'), 'shake', 380)
348:     else animate($('playerSprite'), 'shake', 380)
349:     if (crit) await say(t('battleCrit'), 380)
350:     if (eff > 1.05) { audio.sfx('super'); await say(t('battleSuper'), 480) }
351:     else if (eff < 0.95) await say(t('battleNotVery'), 480)
352:     audio.sfx('hit')
353:     renderBattleUI()
354:     if ((md.drain || 0) > 0) {
355:       const heal = Math.max(1, Math.floor(dealt * md.drain / 100))
356:       attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal)
357:       await say(t('battleRestored', { name: monName(attacker), hp: heal }), 520)
358:       renderBattleUI()
359:     }
360:     if (defender.hp <= 0) {
361:       await faint(defender)
362:       return
363:     }
364:   }
365:   if ((md.healing || 0) > 0 && attacker.hp < attacker.maxHp) {
366:     const heal = Math.max(1, Math.floor(attacker.maxHp * md.healing / 100))
367:     attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal)
368:     await say(t('battleRestored', { name: monName(attacker), hp: heal }), 600)
369:     renderBattleUI()
370:   }
371:   if (md.ailment === 'protect') {
372:     attacker.protected = true
373:     await say(t('battleProtected', { name: monName(attacker) }), 550)
374:   } else if (md.ailment) {
375:     const chance = md.ailmentChance || (md.power ? 0 : 100)
376:     if (Math.random() * 100 < chance) await applyAilment(defender, md.ailment)
377:   }
378:   if (Array.isArray(md.stats) && md.stats.length) {
379:     const target = md.target === 'user' ? attacker : defender
380:     for (const change of md.stats) {
381:       const result = applyStatChange(target, change.stat, change.change)
382:       if (result === 'up') await say(t('battleStatUp', { name: monName(target), stat: t(statLabelKey(change.stat)) }), 520)
383:       else if (result === 'down') await say(t('battleStatDown', { name: monName(target), stat: t(statLabelKey(change.stat)) }), 520)
384:       else if (result == null && target.stages[change.stat] != null) {
385:         await say(t(change.change > 0 ? 'battleStatMax' : 'battleStatMin', { name: monName(target), stat: t(statLabelKey(change.stat)) }), 520)
386:       }
387:     }
388:     renderBattleUI()
389:   }
390:   if (md.flinch && Math.random() * 100 < md.flinch) defender.flinched = true
391: }
