627:     await say(t('battleItemCure', { item: t(item.key), name: monName(pm) }), 700)
628:   } else if (item.kind === 'revive') {
629:     const target = state.team.find(m => m.hp <= 0 && !m.lost)
630:     if (!target) {
631:       await say(t('notNeeded'), 550)
632:       battle.busy = false
633:       renderActions('bag')
