395:   isWalkableTile(x, y) {
396:     const t = this.get(x, y)
397:     return t === T.GRASS || t === T.PATH || t === T.TALL || t === T.FLOWER || t === T.STONE || t === T.SAND || t === T.BRIDGE || t === T.SOIL || t === T.LILY
398:   }
