216: function chooseEnemyMove() {
217:   const em = enemyMon()
218:   if (!em) return 'struggle'
219:   const usable = em.moves.filter(m => m.pp > 0)
220:   if (!usable.length) return 'struggle'
221:   const target = allyMon()
222:   const defTypes = species(target?.id)?.types || []
223:   let best = usable[0]
224:   let bestScore = -1
225:   for (const slot of usable) {
226:     const md = moveData(slot.id)
227:     if (!md) continue
228:     const type = moveTypeFor(slot.id)
229:     const eff = effectiveness(type, defTypes)
230:     const stab = species(em.id)?.types.includes(type) ? 1.5 : 1
231:     let score = (md.power || 0) * eff * stab
232:     if (!md.power) score = 12 + (target?.status ? -8 : 0) + Math.random() * 8
233:     score += Math.random() * 10
234:     if (score > bestScore) { bestScore = score; best = slot }
235:   }
236:   return best.id
237: }
