393: async function applyAilment(target, ailment) {
394:   if (!target || target.hp <= 0) return
395:   if (target.status) {
396:     await say(t('battleStatusAlready', { name: monName(target), status: statusLabel(target.status) }), 520)
397:     return
398:   }
399:   const types = species(target.id)?.types || []
400:   if (ailment === 'burn' && types.includes('fire')) return
401:   if (ailment === 'poison' && (types.includes('poison') || types.includes('steel'))) return
402:   if (ailment === 'paralysis' && types.includes('electric')) return
403:   if (ailment === 'sleep' || ailment === 'freeze') {
404:     target.status = 'sleep'
405:     target.sleepTurns = 2 + Math.floor(Math.random() * 3)
406:     await say(t('battleStatusInflicted', { name: monName(target), status: statusLabel('sleep') }), 600)
407:   } else if (['burn', 'poison', 'paralysis'].includes(ailment)) {
408:     target.status = ailment
409:     await say(t('battleStatusInflicted', { name: monName(target), status: statusLabel(ailment) }), 600)
410:   }
411:   renderBattleUI()
412: }
