431: async function faint(mon) {
432:   if (!battle || battle.over) return
433:   const isEnemy = battle.enemyTeam.includes(mon)
434:   if (isEnemy) {
435:     animate($('enemySprite'), 'faint', 600)
436:     audio.sfx('faint')
437:     audio.cry(mon.id)
438:   } else {
439:     animate($('playerSprite'), 'faint', 600)
440:     audio.sfx('faint')
441:   }
442:   await say(t('battleFaint', { name: monName(mon) }), 800)
443:   if (isEnemy) {
444:     const ally = allyMon()
445:     if (ally && ally.hp > 0 && !ally.lost) {
446:       const gain = expGain(mon, battle.kind)
447:       const result = addExp(ally, gain)
448:       await say(t('battleExp', { name: monName(ally), exp: gain }), 620)
449:       if (result.levels > 0) {
450:         await say(t('battleLevelUp', { name: monName(ally), level: ally.level }), 780)
451:         audio.sfx('badge')
452:         const learned = learnMoves(ally)
453:         for (const move of learned) {
454:           await say(t('battleLearned', { name: monName(ally), move: displayMove(move) }), 680)
455:         }
456:         const evo = tryEvolve(ally)
457:         if (evo) {
458:           await say(t('toastEvolution', { name: evo.oldName, evo: evo.newName }), 900)
459:           hooks.toast(t('toastEvolution', { name: evo.oldName, evo: evo.newName }), '✿')
460:           renderBattleUI()
461:         }
462:       }
463:       renderBattleUI()
464:     }
465:     const next = battle.enemyTeam.findIndex((m, i) => i > battle.enemyIndex && m.hp > 0)
466:     if (next >= 0) {
467:       battle.enemyIndex = next
468:       battle.enemyTeam[next].stages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 }
469:       await say(t('battleTrainerNext', { trainer: battle.trainerName, name: monName(battle.enemyTeam[next]) }), 780)
470:       audio.cry(battle.enemyTeam[next].id)
471:       renderBattleUI()
472:     } else {
473:       await winBattle()
474:     }
475:   } else {
476:     if (permadeath()) mon.lost = true
477:     const next = state.team.findIndex(m => !m.lost && m.hp > 0)
478:     if (next >= 0) {
479:       battle.playerIndex = next
480:       renderBattleUI()
481:       await say(t('battleGo', { name: monName(state.team[next]) }), 650)
482:       audio.cry(state.team[next].id)
483:     } else {
484:       await loseBattle()
485:     }
486:   }
487: }
