489: async function winBattle() {
490:   if (!battle || battle.over) return
491:   battle.over = true
492:   battle.busy = true
493:   renderActions()
494:   if (battle.kind !== 'wild') {
495:     await say(t('battleTrainerDefeat', { trainer: battle.trainerName }), 850)
496:     const reward = battle.reward || 0
497:     if (reward) {
498:       state.petals += reward
499:       await say(t('battleReward', { n: reward }), 720)
500:     }
501:     if (battle.arenaId) {
502:       const id = battle.arenaId
503:       state.arenas[id] = true
504:       state.badges[id] = true
505:       const badgeName = t(BADGE_KEYS[id] || 'hudBadges')
506:       audio.sfx('badge')
507:       await say(t('battleBadge', { badge: badgeName }), 1000)
508:       hooks.toast(t('toastBadge', { badge: badgeName }), '✿')
509:       if (Object.values(state.badges).every(Boolean)) {
510:         hooks.toast(t('toastUnlockedHeart'), '◈')
511:       }
512:     }
513:     if (battle.trainerId && !state.defeatedTrainers.includes(battle.trainerId)) {
514:       state.defeatedTrainers.push(battle.trainerId)
515:     }
516:     if (battle.kind === 'boss') {
517:       state.bossDefeated = true
518:       await say(t('npcBossDefeat'), 1100)
519:     }
520:   } else {
521:     await say(t('battleVictory'), 650)
522:   }
523:   if (!permadeath()) {
524:     state.team.forEach(m => { if (m.hp <= 0 && !m.lost) m.hp = Math.max(1, Math.floor(m.maxHp / 2)) })
525:   } else {
526:     removeLostFromTeam()
527:   }
528:   hooks.refresh()
529:   saveGame()
530:   const result = battle.kind === 'boss' ? 'boss' : 'win'
531:   await sleep(650)
532:   closeBattle(result)
533: }
