595: async function useBattleItem(key) {
596:   if (!battle || battle.busy || battle.over) return
597:   if (noBattleItems()) { await say(t('battleNoItems'), 700); renderActions('main'); return }
598:   const item = ITEMS[key]
599:   if (!item || (state.bag[key] || 0) <= 0) { await say(t('noItem', { item: t(item?.key || key) }), 650); renderActions('bag'); return }
600:   if (item.kind === 'ball') { await throwBall(key); return }
601:   const pm = allyMon()
602:   if (!pm) return
603:   battle.busy = true
604:   renderActions()
605:   if (item.kind === 'heal') {
606:     if (pm.hp >= pm.maxHp) {
607:       await say(t('notNeeded'), 550)
608:       battle.busy = false
609:       renderActions('bag')
610:       return
611:     }
612:     state.bag[key]--
613:     const heal = Math.min(item.value, pm.maxHp - pm.hp)
614:     pm.hp += heal
615:     audio.sfx('heal')
616:     await say(t('battleItemHeal', { item: t(item.key), name: monName(pm), hp: heal }), 750)
617:   } else if (item.kind === 'cure') {
618:     if (pm.status !== 'poison') {
619:       await say(t('notNeeded'), 550)
620:       battle.busy = false
621:       renderActions('bag')
622:       return
623:     }
624:     state.bag[key]--
625:     pm.status = ''
626:     audio.sfx('heal')
627:     await say(t('battleItemCure', { item: t(item.key), name: monName(pm) }), 700)
628:   } else if (item.kind === 'revive') {
629:     const target = state.team.find(m => m.hp <= 0 && !m.lost)
630:     if (!target) {
631:       await say(t('notNeeded'), 550)
632:       battle.busy = false
633:       renderActions('bag')
634:       return
635:     }
636:     state.bag[key]--
637:     target.hp = Math.max(1, Math.floor(target.maxHp / 2))
638:     target.status = ''
639:     audio.sfx('heal')
640:     await say(t('battleRevive', { name: monName(target) }), 750)
641:   }
642:   renderBattleUI()
643:   hooks.refresh()
644:   await enemyFreeAttack()
