717:   drawProp(ctx, prop, time) {
718:     const { x, y } = prop
719:     ctx.save()
720:     ctx.translate(x, y)
721:     ctx.scale(prop.scale, prop.scale)
722:     if (prop.kind === 'rock') {
723:       ctx.fillStyle = 'rgba(18,50,28,.15)'
724:       ctx.beginPath(); ctx.ellipse(0, 2, 12, 5, 0, 0, 7); ctx.fill()
725:       ctx.fillStyle = '#9d9d88'
726:       ctx.beginPath(); ctx.roundRect(-9, -12, 18, 14, 6); ctx.fill()
727:       ctx.fillStyle = '#b8b8a1'
728:       ctx.beginPath(); ctx.roundRect(-6, -12, 8, 6, 3); ctx.fill()
729:     } else if (prop.kind === 'mushroom') {
730:       ctx.fillStyle = '#f3e6c8'
731:       ctx.fillRect(-1.5, -8, 3, 9)
732:       ctx.fillStyle = '#e06f63'
733:       ctx.beginPath(); ctx.ellipse(0, -8, 7, 4.5, 0, Math.PI, 0); ctx.fill()
734:       ctx.fillStyle = '#fff3dc'
735:       ctx.beginPath(); ctx.arc(-2, -10, 1.1, 0, 7); ctx.fill()
736:     } else if (prop.kind === 'bush') {
737:       ctx.fillStyle = 'rgba(18,50,28,.14)'
738:       ctx.beginPath(); ctx.ellipse(0, 2, 11, 4, 0, 0, 7); ctx.fill()
739:       ctx.fillStyle = '#4d925a'
740:       ctx.beginPath(); ctx.arc(-6, -5, 8, 0, 7); ctx.fill()
741:       ctx.beginPath(); ctx.arc(6, -5, 8, 0, 7); ctx.fill()
742:       ctx.beginPath(); ctx.arc(0, -10, 9, 0, 7); ctx.fill()
743:     } else if (prop.kind === 'lamp') {
744:       ctx.fillStyle = '#5e4b3a'
745:       ctx.fillRect(-1.5, -26, 3, 28)
746:       ctx.fillStyle = '#f8df8e'
747:       ctx.beginPath(); ctx.roundRect(-5, -34, 10, 11, 3); ctx.fill()
748:       ctx.fillStyle = 'rgba(255,232,145,.22)'
749:       ctx.beginPath(); ctx.arc(0, -29, 16, 0, 7); ctx.fill()
750:     } else if (prop.kind === 'bench') {
751:       ctx.fillStyle = 'rgba(18,50,28,.14)'
752:       ctx.beginPath(); ctx.ellipse(0, 2, 18, 5, 0, 0, 7); ctx.fill()
753:       ctx.fillStyle = '#9a6b43'
754:       ctx.beginPath(); ctx.roundRect(-17, -10, 34, 7, 3); ctx.fill()
